    id integer NOT NULL,
    txn_date date NOT NULL,
    item_id integer NOT NULL,
    txn_type smallint NOT NULL,
    ref_table character varying(100) NOT NULL,
    ref_id integer NOT NULL,
    qty_in numeric(15,3) NOT NULL,
    qty_out numeric(15,3) NOT NULL,
    unit_cost numeric(15,3) NOT NULL,
    value_in numeric(15,3) NOT NULL,
    value_out numeric(15,3) NOT NULL,
    balance numeric(15,3) NOT NULL,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    created_by integer,
    updated_by integer,
    current_value numeric(15,3) DEFAULT '0'::numeric NOT NULL,
    status integer DEFAULT 1 NOT NULL,
    CONSTRAINT ck_stock_ledger_current_value_non_negative CHECK ((current_value >= (0)::numeric)),
    CONSTRAINT ck_stock_ledger_qty_in_non_negative CHECK ((qty_in >= (0)::numeric)),
    CONSTRAINT ck_stock_ledger_qty_out_non_negative CHECK ((qty_out >= (0)::numeric)),
    CONSTRAINT ck_stock_ledger_unit_cost_non_negative CHECK ((unit_cost >= (0)::numeric)),
    CONSTRAINT ck_stock_ledger_value_in_non_negative CHECK ((value_in >= (0)::numeric)),
    CONSTRAINT ck_stock_ledger_value_out_non_negative CHECK ((value_out >= (0)::numeric))
);


